// HasParoki applies the HasEdge predicate on the "paroki" edge.
func HasParoki() predicate.Keuskupan {
	return predicate.Keuskupan(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ParokiTable, ParokiColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasParokiWith applies the HasEdge predicate on the "paroki" edge with a given conditions (other predicates).
func HasParokiWith(preds ...predicate.Paroki) predicate.Keuskupan {
	return predicate.Keuskupan(func(s *sql.Selector) {
		step := newParokiStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Keuskupan) predicate.Keuskupan {
	return predicate.Keuskupan(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Keuskupan) predicate.Keuskupan {
	return predicate.Keuskupan(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Keuskupan) predicate.Keuskupan {
	return predicate.Keuskupan(sql.NotPredicates(p))
}
